/**
 * Core ServiceMediaCover Component
 * Provides low-level access to service cover media via render props
 */
import React from 'react';
/**
 * Render props for CoverMedia component
 */
export interface CoverMediaRenderProps {
    /** Cover media object containing the image string */
    coverMedia: {
        image?: string;
    };
    /** Whether the service has a cover media image */
    hasCoverMedia: boolean;
}
/**
 * Props for CoverMedia component
 */
export interface CoverMediaProps {
    /** Render prop function that receives cover media data */
    children: (props: CoverMediaRenderProps) => React.ReactNode;
}
/**
 * Core component that provides access to service cover media via render props.
 * The cover media is typically used as a hero/banner image.
 * Must be used within a Service.Root context.
 *
 * @component
 * @example
 * ```tsx
 * <ServiceMediaCover.CoverMedia>
 *   {({ coverMedia, hasCoverMedia }) => (
 *     hasCoverMedia ? (
 *       <img src={coverMedia.image} alt="Service Cover" />
 *     ) : (
 *       <div>No cover image available</div>
 *     )
 *   )}
 * </ServiceMediaCover.CoverMedia>
 * ```
 */
export declare function CoverMedia(props: CoverMediaProps): React.ReactNode;
